async function loadDashboardMetrics(){try{const a=await api('/api/analytics');const cards=[['◉',a.totalProfileViews,'Total Views'],['◷',a.todayViews,'Today Views'],['↗',a.totalLinkClicks,'Total Clicks'],['♫',a.musicTracks,'Music Tracks']];const grid=$$('.stat-card');if(grid.length)grid.forEach((el,i)=>{if(cards[i]){el.querySelector('strong').textContent=cards[i][1];el.querySelector('small').textContent=cards[i][2]}})}catch{}}
async function loadAnalytics(){try{const a=await api('/api/analytics');const days=Object.entries(a._viewsByDay||{});const max=Math.max(1,...days.map(x=>x[1]));$('#analyticsView').innerHTML=`<div class="grid grid-4">${stat('◉',a.totalProfileViews,'Total Views')}${stat('◷',a.todayViews,'Today Views')}${stat('↗',a.totalLinkClicks,'Total Clicks')}${stat('♫',a.musicTracks,'Music Tracks')}</div><div class="grid grid-2 section-panel"><div class="panel"><div class="panel-title"><h3>Views</h3><span>Daily</span></div><div class="chart">${days.slice(-14).map(([d,v])=>`<i class="bar-chart" title="${esc(d)}: ${v}" style="--h:${Math.max(5,v/max*100)}%"></i>`).join('')||'<div class="empty">ยังไม่มีข้อมูล</div>'}</div></div><div class="panel"><div class="panel-title"><h3>Top Links</h3><span>Clicks</span></div>${a.topLinks?.map(x=>`<div class="link-item"><div class="drag">↗</div><div class="item-main"><strong>${esc(x.title)}</strong><small>${esc(x.url)}</small></div><div>${x.clicks}</div></div>`).join('')||'<div class="empty">ยังไม่มี Click</div>'}</div></div><div class="panel section-panel"><div class="panel-title"><h3>System</h3><span>${esc(a.lastUpdate||'—')}</span></div><div class="grid grid-4">${stat('●',a.serverStatus,'Server')}${stat('✓',a.apiStatus,'API')}${stat('▣',(a.storageUsage/1024/1024).toFixed(2)+' MB','Storage')}${stat('♫',a.youtubeMusic+' / '+a.localMusic,'YouTube / Local')}</div></div>`}catch(e){$('#analyticsView').innerHTML=`<div class="error-box">โหลด Analytics ไม่สำเร็จ <button class="btn" onclick="location.reload()">Retry</button></div>`}}
async function refreshState(){const d=await api('/api/profile');state.profile=d.profile||{};state.links=state.profile.links||[];state.music=state.profile.music||[];state.profileCard=state.profile.profileCard||{};state.appearance=state.profile.appearance||{};state.background=state.profile.backgroundSettings||state.profile.background||{};state.visualizer=state.profile.visualizer||{};state.branding=state.profile.branding||{};try{state.background=(await api('/api/background')).background||state.background}catch{}try{state.settings=(await api('/api/settings')).settings||{}}catch{};route(currentSection||'dashboard')}
